/** Dependency-free UTF-16 well-formedness check for runtimes before ES2024. */
const apply = Reflect.apply;
const stringCharCodeAt = String.prototype.charCodeAt;
/** Return whether every UTF-16 surrogate in the string belongs to a valid pair. */
export function isWellFormedString(value) {
    for (let index = 0; index < value.length; index++) {
        const codeUnit = apply(stringCharCodeAt, value, [index]);
        if (codeUnit >= 0xD800 && codeUnit <= 0xDBFF) {
            index++;
            if (index >= value.length)
                return false;
            const trailingCodeUnit = apply(stringCharCodeAt, value, [index]);
            if (trailingCodeUnit < 0xDC00 || trailingCodeUnit > 0xDFFF)
                return false;
        }
        else if (codeUnit >= 0xDC00 && codeUnit <= 0xDFFF) {
            return false;
        }
    }
    return true;
}
